let phone = $input.first().json.query ? $input.first().json.query.phone : $input.first().json.phone;
if (!phone) return [{json: {phone: ''}}];
phone = phone.replace(/[\s\-+()]/g, '');
if (phone.startsWith('54')) phone = phone.substring(2);
if (phone.startsWith('0')) phone = phone.substring(1);
if (phone.length > 8 && phone.includes('15') && phone.indexOf('15') > 1 && phone.indexOf('15') <= 4) {
  phone = phone.replace('15', '4');
}
return [{json: {phone: phone}}];
